const REFERENCE_DATE = new Date('2026-09-15');

const orders = $input.all().map(item => item.json);

// گروه‌بندی سفارش‌ها بر اساس مشتری
const customers = {};
for (const o of orders) {
  const id = o.customer_id;
  if (!customers[id]) {
    customers[id] = {
      customer_id: id,
      customer_name: o.customer_name,
      city: o.city,
      signup_date: o.signup_date,
      order_dates: [],
      order_count: 0,
      total_amount: 0,
    };
  }
  customers[id].order_dates.push(new Date(o.order_date));
  customers[id].order_count += 1;
  customers[id].total_amount += Number(o.order_amount) || 0;
}

const DAY_MS = 1000 * 60 * 60 * 24;

const result = Object.values(customers).map(c => {
  const lastOrder = new Date(Math.max(...c.order_dates.map(d => d.getTime())));
  const recency = Math.round((REFERENCE_DATE - lastOrder) / DAY_MS);
  const daysSinceSignup = Math.round((REFERENCE_DATE - new Date(c.signup_date)) / DAY_MS);

  return {
    json: {
      customer_id: c.customer_id,
      customer_name: c.customer_name,
      city: c.city,
      signup_date: c.signup_date,
      last_order_date: lastOrder.toISOString().split('T')[0],
      days_since_signup: daysSinceSignup,
      Recency: recency,
      Frequency: c.order_count,
      Monetary: c.total_amount,
    }
  };
});

return result;

const customers = $input.all().map(item => item.json);
const n = customers.length;

// --- نمره R: بازه‌های مطلق روز ---
function scoreRecency(days) {
  if (days <= 7) return 5;
  if (days <= 14) return 4;
  if (days <= 30) return 3;
  if (days <= 90) return 2;
  return 1;
}

// --- نمره F و M: رتبه‌بندی صدکی با min rank برای مدیریت Tie ---
function quantileScore(values, value) {
  // min rank: تعداد مقادیر کوچک‌تر + 1  → مقادیر برابر رتبه‌ی یکسان می‌گیرند
  const rank = values.filter(v => v < value).length + 1;
  const score = Math.ceil(rank / (n / 5));
  return Math.min(Math.max(score, 1), 5); // محدود کردن به بازه 1..5
}

const frequencies = customers.map(c => c.Frequency);
const monetaries = customers.map(c => c.Monetary);

const scored = customers.map(c => {
  const R_Score = scoreRecency(c.Recency);
  const F_Score = quantileScore(frequencies, c.Frequency);
  const M_Score = quantileScore(monetaries, c.Monetary);

  // --- قوانین سگمنت: به ترتیب، اولین شرط true برنده است ---
  let Segment;
  if (c.days_since_signup <= 90 && c.Frequency <= 2) {
    Segment = 'New Customers';
  } else if (R_Score >= 4 && F_Score >= 4 && M_Score >= 4) {
    Segment = 'Champions';
  } else if (R_Score <= 2 && (F_Score >= 3 || M_Score >= 3)) {
    Segment = 'At Risk';
  } else if (R_Score <= 2) {
    Segment = 'Lost Customers';
  } else {
    Segment = 'Loyal Customers';
  }

  return {
    json: {
      customer_id: c.customer_id,
      customer_name: c.customer_name,
      Recency: c.Recency,
      Frequency: c.Frequency,
      Monetary: c.Monetary,
      R_Score,
      F_Score,
      M_Score,
      RFM_Score: `${R_Score}${F_Score}${M_Score}`,
      Segment,
      analysis_date: '2026-09-15',
    }
  };
});

// مرتب‌سازی: بهترین مشتری‌ها اول
scored.sort((a, b) => Number(b.json.RFM_Score) - Number(a.json.RFM_Score));

return scored;
